import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceArea, Label } from 'recharts';
import { ArrowLeft, Calendar, ChevronDown, AlertCircle, Search, Users, Activity, Building2, Database, AlertTriangle, HeartPulse, X, Loader2, ChevronLeft, Copy, Printer, ShieldCheck, ClipboardCheck, Pill, ChevronRight } from 'lucide-react';

const API_BASE = "http://127.0.0.1:5000/api";

function App() {
  const [view, setView] = useState('overview');
  const [patients, setPatients] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [clinicalData, setClinicalData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  // 搜尋與介面狀態
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [selectedDrug, setSelectedDrug] = useState(null);
  const [stats, setStats] = useState({ total: 0, with_reactions: 0 });
  const [showCategories, setShowCategories] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [currentLabel, setCurrentLabel] = useState('');
  const [showCopyToast, setShowCopyToast] = useState(false);
  const [startIndex, setStartIndex] = useState(0);
  const [windowSize, setWindowSize] = useState(14);
  const categories = ["心臟血管系統", "呼吸系統", "消化系統", "神經系統", "內分泌系統"];

  useEffect(() => {
    fetch(`${API_BASE}/patients`).then(res => res.json()).then(json => { if (json.status === "success") setPatients(json.data); }).finally(() => setIsLoading(false));
    fetch(`${API_BASE}/stats`).then(res => res.json()).then(setStats).catch(() => {});
  }, []);

  const performSearch = (params, label) => {
    setIsLoading(true); setCurrentLabel(label);
    fetch(`${API_BASE}/search`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(params) })
    .then(res => res.json()).then(json => setSearchResults(json.data)).finally(() => setIsLoading(false));
  };

  const handleSelectPatient = (p) => {
    setSelectedPatient(p); setClinicalData(p.clinicalData); setStartIndex(0); setView('dashboard');
  };

  const renderSidebar = () => (
    <div className="w-72 bg-white border-r border-slate-100 flex flex-col p-8 print:hidden">
      <div className="flex items-center gap-3 mb-12 px-2">
        <Activity size={32} className="text-blue-600" />
        <span className="text-2xl font-black italic text-slate-800">ADR <span className="text-blue-600">PRO</span></span>
      </div>
      <nav className="flex-1 space-y-2">
        <button onClick={() => setView('overview')} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-bold transition-all ${view === 'overview' ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}><Users size={20} /> 患者住院紀錄</button>
        <button onClick={() => setView('repository')} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-bold transition-all ${view === 'repository' || view === 'drug_detail' ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}><Search size={20} /> 藥物查詢</button>
      </nav>
    </div>
  );

  const renderDashboard = () => {
    if(!clinicalData) return <div className="flex-1 flex items-center justify-center">載入中...</div>;
    const visibleTrends = clinicalData.trends.slice(startIndex, startIndex + windowSize);
    return (
      <div className="flex-1 p-8 overflow-y-auto bg-[#F8FAFC]">
        <div className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            <button onClick={() => setView('overview')} className="p-3 bg-white border rounded-xl shadow-sm hover:bg-slate-50"><ArrowLeft size={18} /></button>
            <div className="bg-white px-6 py-3 rounded-2xl border flex items-center gap-3 font-bold text-slate-700 shadow-sm"><Calendar size={16} className="text-blue-500"/> 05/01 - 05/11</div>
          </div>
          <div className="flex gap-2">
            {[3, 7, 14].map(d => (
              <button key={d} onClick={() => { setWindowSize(d); setStartIndex(0); }} className={windowSize === d ? "px-6 py-2 rounded-lg bg-blue-600 text-white font-bold text-xs" : "px-6 py-2 bg-white text-slate-400 border font-bold text-xs shadow-sm"}>{d}D</button>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-[2.5rem] p-10 border border-slate-100 shadow-sm mb-8">
          <div className="h-80 w-full mb-6">
            <ResponsiveContainer>
              <LineChart data={visibleTrends}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11, fontWeight: 'bold'}} />
                <YAxis yAxisId="na" domain={[120, 160]} axisLine={false} tickLine={false} tick={{fill: '#F97316', fontSize: 10, fontWeight: 'bold'}} width={40} />
                <YAxis yAxisId="k" orientation="right" domain={[2, 8]} axisLine={false} tickLine={false} tick={{fill: '#6366F1', fontSize: 10, fontWeight: 'bold'}} width={40} />
                <Tooltip contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', fontWeight: 'bold' }} />
                <ReferenceArea yAxisId="na" y1={135} y2={145} fill="#F97316" fillOpacity={0.05} stroke="none" />
                <ReferenceArea yAxisId="k" y1={3.5} y2={5.0} fill="#6366F1" fillOpacity={0.05} stroke="none" />
                <Line yAxisId="na" type="monotone" dataKey="na" stroke="#F97316" strokeWidth={5} dot={{r: 6, fill: '#F97316', stroke: '#fff', strokeWidth: 3}} isAnimationActive={false} />
                <Line yAxisId="k" type="monotone" dataKey="k" stroke="#6366F1" strokeWidth={5} dot={{r: 6, fill: '#6366F1', stroke: '#fff', strokeWidth: 3}} isAnimationActive={false} />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <div className="px-10 mb-12">
            <input type="range" min="0" max={Math.max(0, clinicalData.trends.length - windowSize)} value={startIndex} onChange={(e) => setStartIndex(parseInt(e.target.value))} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600" />
            <div className="flex justify-between text-[10px] font-black text-slate-400 mt-4">
              <span>住院開始 (05/01)</span>
              <span className="text-blue-600 font-bold bg-blue-50 px-4 py-1.5 rounded-full border border-blue-100">平移檢視: {visibleTrends[0]?.date} - {visibleTrends[visibleTrends.length-1]?.date}</span>
              <span>住院結束 (05/11)</span>
            </div>
          </div>
          <div className="space-y-4 pt-10 border-t border-slate-100">
            {clinicalData.gantt.map((med, i) => {
              const left = Math.max(0, ((med.startIdx - startIndex) / windowSize) * 100);
              const right = Math.min(100, ((med.endIdx - startIndex + 1) / windowSize) * 100);
              const width = Math.max(0, right - left);
              return (
                <div key={i} className="flex items-center">
                  <div className="w-48 text-left pr-4">
                    <p className="text-[11px] font-black text-slate-700 italic uppercase">{med.name}</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase">{med.type}</p>
                  </div>
                  <div className="flex-1 h-10 bg-slate-50 rounded-xl relative overflow-hidden border border-slate-100">
                    {width > 0 && <div className="absolute h-full opacity-80 rounded-lg flex items-center px-4" style={{ left: left + '%', width: width + '%', backgroundColor: med.color }}>
                      <span className="text-[8px] text-white font-black whitespace-nowrap">{med.startDate} - {med.endDate}</span>
                    </div>}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white rounded-3xl p-10 border border-slate-100 shadow-sm mb-8 text-left">
           <h2 className="font-black text-slate-700 mb-8 border-l-4 border-blue-600 pl-4 italic uppercase tracking-tighter">實際用藥全紀錄</h2>
           <table className="w-full text-sm">
              <thead className="text-slate-400 border-b text-left"><tr><th className="pb-4">藥物名稱</th><th className="pb-4">開始時間</th><th className="pb-4">停止時間</th><th className="pb-4 text-right">狀態</th></tr></thead>
              <tbody className="divide-y divide-slate-50">
                {clinicalData.logs.map((log, i) => (
                  <tr key={i} className="hover:bg-slate-50 transition-all">
                    <td className="py-6 font-black italic text-slate-700">{log.name}</td>
                    <td className="py-6 text-slate-400 font-mono">{log.start}</td>
                    <td className="py-6 text-slate-400 font-mono">{log.end}</td>
                    <td className="py-6 text-right"><span className={log.status === 'ACTIVE' ? "text-emerald-500 bg-emerald-50 px-3 py-1 rounded-full font-bold" : "text-slate-400 bg-slate-100 px-3 py-1 rounded-full font-bold"}>{log.status}</span></td>
                  </tr>
                ))}
              </tbody>
           </table>
        </div>
      </div>
    );
  };

  const renderRepository = () => (
    <div className="flex-1 overflow-y-auto relative bg-[#f8fafc] print:hidden">
      <div className={"w-full flex flex-col items-center transition-all duration-500 " + (searchResults.length > 0 ? "pt-8 pb-6 border-b bg-white sticky top-0 z-50 shadow-sm" : "pt-[20vh]")}>
        <div className={"text-center transition-all " + (searchResults.length > 0 ? "mb-4 flex items-center gap-3" : "mb-8")}>
          <h1 className={"font-bold text-[#0f4c81] flex items-center justify-center gap-2 " + (searchResults.length > 0 ? "text-2xl" : "text-4xl")}><Building2 size={searchResults.length > 0 ? 28 : 40} /> 台北榮總藥物查詢</h1>
        </div>
        <div className="w-full max-w-2xl px-6">
          <div className="flex items-center bg-white border rounded-full px-6 py-3 shadow-lg">
            <Search className="text-slate-400 mr-3 cursor-pointer" size={22} onClick={() => performSearch({ keyword: searchQuery.trim() }, "搜尋：" + searchQuery)} />
            <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && performSearch({ keyword: searchQuery.trim() }, "搜尋：" + searchQuery)} className="flex-1 outline-none text-xl text-slate-800 bg-transparent" placeholder="輸入藥名或代碼..." />
            {searchQuery && <X className="text-slate-400 cursor-pointer ml-3" size={24} onClick={() => { setSearchQuery(''); setSearchResults([]); }} />}
          </div>
        </div>
        <div className="flex flex-wrap justify-center gap-4 mt-8 px-6 font-bold text-sm">
          <button onClick={() => performSearch({}, '完整收錄藥物')} className="flex items-center gap-2 px-5 py-2 rounded-full border border-[#0f4c81] text-[#0f4c81] hover:bg-[#0f4c81] hover:text-white bg-white transition-all"><Database size={18} /> 收錄藥物 <span className="bg-[#0f4c81] text-white px-2 py-0.5 rounded-full text-xs">{stats.total}</span></button>
          <button onClick={() => setShowCategories(!showCategories)} className="flex items-center gap-2 px-5 py-2 rounded-full border border-emerald-600 text-emerald-600 hover:bg-emerald-600 hover:text-white bg-white transition-all"><HeartPulse size={18} /> 身體反應分類 <ChevronDown size={16}/></button>
        </div>
      </div>
      {searchResults.length > 0 && (
        <div className="max-w-5xl mx-auto p-8">
          <div className="bg-white border rounded-2xl overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-slate-500 text-sm border-b"><tr><th className="p-5 w-32 text-center">藥碼</th><th className="p-5">藥物名稱</th><th className="p-5 text-right">狀態</th></tr></thead>
              <tbody className="divide-y divide-slate-100">
                {searchResults.map((drug, i) => (
                  <tr key={i} className="cursor-pointer hover:bg-blue-50 transition-all" onClick={() => { setSelectedDrug(drug); setView('drug_detail'); }}>
                    <td className="p-5 font-mono text-slate-500 font-bold text-center">{drug.id}</td>
                    <td className="p-5 font-black text-[#0f4c81] text-lg">{drug.name}</td>
                    <td className="p-5 text-right"><span className="bg-rose-50 text-rose-600 px-4 py-1.5 rounded-full text-xs font-black border border-rose-200">注意不良反應</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-left overflow-hidden">
      {renderSidebar()}
      {view === 'overview' && (
        <div className="flex-1 p-12 overflow-y-auto">
          <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase tracking-tighter">患者住院紀錄</h1>
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden max-w-6xl">
            <table className="w-full text-left">
              <tbody className="divide-y divide-slate-50">
                {patients.map(p => (
                  <tr key={p.id} onClick={() => handleSelectPatient(p)} className="hover:bg-blue-50/50 cursor-pointer group transition-all">
                    <td className="py-6 px-8 font-black text-blue-600">{p.id}</td>
                    <td className="py-6 px-8 text-slate-700 font-bold">{p.name} <span className="text-slate-400 font-normal ml-1">{p.info}</span></td>
                    <td className="py-6 px-8 text-center font-bold">{p.na} / {p.k}</td>
                    <td className="py-6 px-8 text-right pr-12"><span className="bg-rose-50 text-rose-600 px-5 py-1.5 rounded-full text-[11px] font-bold border border-rose-100">{p.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {view === 'dashboard' && renderDashboard()}
      {view === 'repository' && renderRepository()}
      {view === 'drug_detail' && selectedDrug && (
        <div className="flex-1 overflow-y-auto bg-[#f8fafc]">
          <div className="sticky top-0 bg-white border-b-4 border-[#0f4c81] p-6 flex justify-between items-center z-50">
            <button onClick={() => setView('repository')} className="flex items-center gap-2 px-5 py-2 bg-slate-100 rounded-full font-bold"><ChevronLeft size={18}/> 返回查詢</button>
            <h1 className="text-3xl font-black text-[#0f4c81]">{selectedDrug.name}</h1>
            <button onClick={() => window.print()} className="px-5 py-2 bg-slate-100 rounded-full font-bold">列印</button>
          </div>
          <div className="max-w-6xl mx-auto p-12">
            <div className="bg-white rounded-2xl p-10 shadow-sm border-l-[6px] border-rose-600">
              <h2 className="text-2xl font-black text-rose-600 mb-6 flex items-center gap-3 border-b pb-4"><AlertTriangle size={28}/> 不良反應</h2>
              <div className="text-slate-700 leading-relaxed text-lg whitespace-pre-line">{selectedDrug.adverse_reaction}</div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
